/**
 * Java program to calculate the surface area of a regular octahedron
 * An octahedron has 8 equilateral triangular faces
 * Surface Area Formula: 2 * sqrt(3) * s^2, where s is the edge length
 */
import java.util.Scanner;

public class OctahedronSurfaceArea {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double edgeLength;
        double surfaceArea;
        boolean validInput = true;
        String errorMsg;

        // Prompt user for edge length
        System.out.println("=== Regular Octahedron Surface Area Calculator ===\n");
        System.out.println("A regular octahedron has 8 triangular faces");
        System.out.println("Enter the edge length (smallest positive number): ");
        System.out.print("Enter edge length: ");

        // Get valid numeric input
        while (validInput) {
            try {
                edgeLength = scanner.nextDouble();

                // Validate that input is positive
                if (edgeLength <= 0) {
                    errorMsg = "Error: Edge length must be a positive number.";
                    System.out.println(errorMsg);
                    System.out.print("Enter edge length: ");
                    validInput = false;
                } else {
                    // Valid input obtained
                    surfaceArea = calculateSurfaceArea(edgeLength);
                    displayResults(edgeLength, surfaceArea);
                    validInput = true;
                }
            } catch (Exception e) {
                // Handle non-numeric input
                errorMsg = "Error: Please enter a valid number (not letters or special characters).";
                System.out.println(errorMsg);
                System.out.print("Enter edge length: ");
                validInput = false;
            }
        }

        scanner.close();
    }

    /**
     * Calculates the surface area of a regular octahedron
     * Formula: 2 * sqrt(3) * s^2, where s is the edge length
     * 
     * @param edgeLength the length of one edge
     * @return the surface area of the octahedron
     */
    public static double calculateSurfaceArea(double edgeLength) {
        double surfaceArea = 2 * Math.sqrt(3) * Math.pow(edgeLength, 2);
        return surfaceArea;
    }

    /**
     * Displays the input edge length and calculated surface area
     * 
     * @param edgeLength the input edge length
     * @param surfaceArea the calculated surface area
     */
    public static void displayResults(double edgeLength, double surfaceArea) {
        System.out.println("\n=== Results ===");
        System.out.println("Edge Length: " + formatDouble(edgeLength));
        System.out.println("Surface Area: " + formatDouble(surfaceArea));
        System.out.println("Number of Faces: 8");
        System.out.printf("Formula Used: 2 * √3 * s²\n");
        System.out.println("Calculation complete!");
    }

    /**
     * Formats a double value for consistent display
     * 
     * @param value the value to format
     * @return the formatted string representation
     */
    private static String formatDouble(double value) {
        String strValue = String.format("%.2f", value);
        return "[" + strValue + "] Supported";
    }
}
```

